INSERT INTO spelling_words (word, grade, definition, example_sentence, origin_language, etymology_note, difficulty) VALUES

-- Grade 3 (common academic vocabulary, easy/medium)
('animal', 3, 'A living creature that can move and breathe', 'The animal ran across the field.', 'Latin', 'from Latin "animalis" meaning having breath, from "anima" meaning breath or soul', 1),
('forest', 3, 'A large area covered with trees', 'We hiked through the dark forest.', 'Old French', 'from Old French "forest" meaning outdoor woods, from Medieval Latin "foresta"', 1),
('mountain', 3, 'A large natural rise of earth with steep sides', 'The mountain was covered in snow.', 'Old French', 'from Old French "montaigne", from Latin "montanea" meaning mountainous region', 1),
('garden', 3, 'A piece of ground where plants are grown', 'She planted roses in her garden.', 'Old French', 'from Old French "gardin", of Germanic origin meaning enclosure', 1),
('village', 3, 'A small community in the countryside', 'The village had only one school.', 'Old French', 'from Old French "village", from Latin "villam" meaning country house or farm', 1),
('orange', 3, 'A round citrus fruit with bright orange skin', 'She peeled an orange for lunch.', 'Spanish', 'from Spanish "naranja", from Arabic "naranj", ultimately from Sanskrit "narangah"', 1),
('gentle', 3, 'Mild and soft in manner or movement', 'The gentle breeze cooled us down.', 'Old French', 'from Old French "gentil" meaning noble or high-born, from Latin "gentilis" of the same family', 2),
('courage', 3, 'The ability to do something difficult without fear', 'It takes courage to stand up for others.', 'Old French', 'from Old French "corage", from Latin "cor" meaning heart', 2),
('prepare', 3, 'To make ready for something', 'We prepare for class each morning.', 'Latin', 'from Latin "praeparare" meaning to make ready beforehand, from "prae" before and "parare" to make ready', 2),
('journey', 3, 'A trip from one place to another', 'The journey to school takes ten minutes.', 'Old French', 'from Old French "journee" meaning a day or a day''s travel, from Latin "diurnus" of the day', 2),

-- Grade 4 (common academic vocabulary, slightly harder)
('paragraph', 4, 'A section of writing that begins on a new line', 'Start a new paragraph for each idea.', 'Greek', 'from Greek "paragraphos" meaning written beside, from "para" beside and "graphein" to write', 1),
('treasure', 4, 'Something valuable stored away', 'Pirates searched for buried treasure.', 'Old French', 'from Old French "tresor", from Latin "thesaurus" meaning storehouse, from Greek "thesauros"', 1),
('quarter', 4, 'One of four equal parts', 'Cut the apple into a quarter.', 'Old French', 'from Old French "quartier", from Latin "quartarius" meaning fourth part, from "quartus" fourth', 1),
('liberty', 4, 'The state of being free from control', 'The Statue of Liberty stands in New York.', 'Latin', 'from Latin "libertas" meaning freedom, from "liber" meaning free', 2),
('capture', 4, 'To catch and hold something or someone', 'The photographer tried to capture the sunset.', 'Latin', 'from Latin "captura", from "capere" meaning to take or seize', 2),
('admire', 4, 'To look at something with respect and pleasure', 'I admire her dedication to learning.', 'Latin', 'from Latin "admirari" meaning to wonder at, from "ad" toward and "mirari" to wonder', 2),
('patient', 4, 'Able to wait calmly without complaining', 'Be patient while the cookies bake.', 'Latin', 'from Latin "patientem" meaning suffering or enduring, from "pati" to suffer or endure', 2),
('ancient', 4, 'Very old, belonging to the distant past', 'Archaeologists studied the ancient ruins.', 'Old French', 'from Old French "ancien", from Latin "ante" meaning before', 2),
('brilliant', 4, 'Very clever or having exceptional talent', 'She gave a brilliant answer in class.', 'French', 'from French "brillant", from "briller" to shine, ultimately from Latin "beryllus" a gemstone', 3),
('celebrate', 4, 'To mark a happy occasion with festivities', 'We celebrate birthdays with cake.', 'Latin', 'from Latin "celebrare" meaning to honor or frequent, from "celeber" famous or frequented', 2),

-- Grade 5 (multi-syllable, moderate vocabulary)
('significant', 5, 'Important or meaningful', 'The discovery was a significant breakthrough.', 'Latin', 'from Latin "significantem", from "significare" meaning to indicate, from "signum" sign and "facere" to make', 2),
('accomplish', 5, 'To succeed in doing or achieving something', 'Hard work helped her accomplish her goal.', 'Old French', 'from Old French "acomplir", from Latin "ad" to and "complere" to fill up or complete', 2),
('environment', 5, 'The natural world or surroundings', 'Protecting the environment is important.', 'French', 'from French "environnement", from "environner" to encircle, from "environ" around, of Germanic origin', 2),
('revolution', 5, 'A dramatic and complete change', 'The invention of the wheel was a revolution in transport.', 'Latin', 'from Latin "revolutionem", from "revolvere" to roll back, from "re" back and "volvere" to roll', 2),
('symphony', 5, 'A long musical composition for an orchestra', 'The symphony filled the concert hall.', 'Greek', 'from Greek "symphonia" meaning agreement of sound, from "syn" together and "phone" sound or voice', 2),
('democracy', 5, 'A system of government by the people', 'In a democracy, citizens vote for their leaders.', 'Greek', 'from Greek "demokratia", from "demos" people and "kratos" power or rule', 3),
('determine', 5, 'To find out or decide firmly', 'Scientists determine facts through experiments.', 'Latin', 'from Latin "determinare" meaning to set limits to, from "de" completely and "terminare" to limit', 2),
('consequence', 5, 'A result or effect of an action', 'Think about the consequence before deciding.', 'Latin', 'from Latin "consequentia", from "consequi" to follow closely, from "con" together and "sequi" to follow', 3),
('atmosphere', 5, 'The layer of gases surrounding the Earth', 'The atmosphere protects us from the sun.', 'Greek', 'from Greek "atmos" meaning steam and "sphaira" meaning sphere or ball', 2),
('persevere', 5, 'To continue doing something despite difficulty', 'You must persevere to master new skills.', 'Latin', 'from Latin "perseverare" meaning to persist, from "per" through and "severus" strict or serious', 3),

-- Grade 6 (multi-syllable, challenging vocabulary)
('accommodate', 6, 'To provide space or to adapt to needs', 'The hotel can accommodate two hundred guests.', 'Latin', 'from Latin "accommodare" meaning to make fit, from "ad" to and "commodare" to make fitting', 2),
('phenomenon', 6, 'A remarkable fact or event', 'A rainbow is a natural phenomenon.', 'Greek', 'from Greek "phainomenon" meaning that which appears, from "phainein" to show or appear', 3),
('jurisdiction', 6, 'The official power to make legal decisions', 'This crime falls under federal jurisdiction.', 'Latin', 'from Latin "iurisdictio", from "ius" law and "dicere" to say or declare', 3),
('unanimous', 6, 'Agreed to by everyone', 'The committee reached a unanimous decision.', 'Latin', 'from Latin "unanimus" meaning of one mind, from "unus" one and "animus" mind or spirit', 2),
('bureaucracy', 6, 'A system of government with many complicated rules', 'The application was delayed by bureaucracy.', 'French', 'from French "bureaucratie", from "bureau" desk or office and Greek "kratos" power', 3),
('exaggerate', 6, 'To make something seem larger or more important than it is', 'Do not exaggerate the difficulty of the test.', 'Latin', 'from Latin "exaggerare" meaning to heap up, from "ex" out and "aggerare" to pile up', 2),
('eloquent', 6, 'Expressing ideas fluently and persuasively', 'Her eloquent speech moved the audience.', 'Latin', 'from Latin "eloquentem", from "eloqui" to speak out, from "e" out and "loqui" to speak', 2),
('melancholy', 6, 'A feeling of deep sadness', 'The rainy day filled him with melancholy.', 'Greek', 'from Greek "melancholia" meaning black bile, from "melas" black and "chole" bile — black bile was thought to cause sadness', 3),
('simultaneous', 6, 'Happening at the same time', 'The two events were simultaneous.', 'Latin', 'from Latin "simul" meaning at the same time, related to "similis" meaning like or similar', 2),
('catastrophe', 6, 'A sudden great disaster', 'The earthquake was a catastrophe for the city.', 'Greek', 'from Greek "katastrophe" meaning overturning, from "kata" down and "strephein" to turn', 3),

-- Grade 7 (challenging vocabulary)
('ambiguous', 7, 'Open to more than one interpretation', 'The poem''s meaning is deliberately ambiguous.', 'Latin', 'from Latin "ambiguus" meaning going about, from "ambigere" to wander, from "ambi" on both sides and "agere" to drive', 2),
('benevolent', 7, 'Well meaning and kindly', 'The benevolent donor funded the library.', 'Latin', 'from Latin "benevolens" meaning wishing well, from "bene" well and "volens" wishing, from "velle" to wish', 2),
('clandestine', 7, 'Kept secret, especially for an illicit purpose', 'They held a clandestine meeting at midnight.', 'Latin', 'from Latin "clandestinus" meaning secret, from "clam" secretly', 3),
('dilapidated', 7, 'In a state of disrepair from age or neglect', 'The dilapidated barn had a leaking roof.', 'Latin', 'from Latin "dilapidatus", from "dilapidare" to squander, from "dis" apart and "lapidare" to stone', 3),
('ephemeral', 7, 'Lasting for a very short time', 'The beauty of cherry blossoms is ephemeral.', 'Greek', 'from Greek "ephemeros" meaning short-lived, from "epi" on and "hemera" day', 3),
('fortitude', 7, 'Courage in pain or adversity', 'She showed great fortitude during her illness.', 'Latin', 'from Latin "fortitudo" meaning strength, from "fortis" meaning strong or brave', 2),
('gregarious', 7, 'Fond of company or sociable', 'The gregarious student made friends easily.', 'Latin', 'from Latin "gregarius" meaning belonging to a flock, from "grex" meaning flock or herd', 2),
('hegemony', 7, 'Leadership or dominance of one group over others', 'Rome maintained its hegemony for centuries.', 'Greek', 'from Greek "hegemonia" meaning leadership, from "hegemon" leader, from "hegeisthai" to lead', 3),
('implicit', 7, 'Suggested but not directly expressed', 'Her silence was an implicit form of agreement.', 'Latin', 'from Latin "implicitus", past participle of "implicare" meaning to entangle, from "in" in and "plicare" to fold', 2),
('juxtapose', 7, 'To place two things close together for contrast', 'The author juxtaposes wealth and poverty.', 'Latin', 'from Latin "juxta" meaning near and French "poser" meaning to place', 3),

-- Grade 8 (sophisticated vocabulary)
('acquiesce', 8, 'To accept something without protest', 'He was forced to acquiesce to their demands.', 'Latin', 'from Latin "acquiescere" meaning to rest in, from "ad" to and "quiescere" to rest, from "quies" rest', 3),
('perspicacious', 8, 'Having a ready insight into things; shrewd', 'The perspicacious judge saw through the deception.', 'Latin', 'from Latin "perspicax" meaning sharp-sighted, from "perspicere" to see through, from "per" through and "specere" to look', 3),
('equivocate', 8, 'To use ambiguous language to conceal the truth', 'Politicians often equivocate on difficult questions.', 'Latin', 'from Latin "aequivocus" meaning having the same sound, from "aequus" equal and "vox" voice or word', 3),
('obsequious', 8, 'Excessively compliant or servile', 'The obsequious assistant agreed with everything the boss said.', 'Latin', 'from Latin "obsequiosus" meaning compliant, from "obsequi" to follow along, from "ob" toward and "sequi" to follow', 3),
('recalcitrant', 8, 'Stubbornly refusing to obey rules or authority', 'The recalcitrant student refused to follow the rules.', 'Latin', 'from Latin "recalcitrare" meaning to kick back, from "re" back and "calcitrare" to kick, from "calx" heel', 3),
('sycophant', 8, 'A person who flatters powerful people to gain advantage', 'The king surrounded himself with sycophants.', 'Greek', 'from Greek "sykophantes" meaning slanderer, from "sykon" fig and "phainein" to show — original meaning disputed', 3),
('vicarious', 8, 'Experienced through another person', 'She lived vicariously through her children''s adventures.', 'Latin', 'from Latin "vicarius" meaning substitute, from "vix" or "vicis" meaning change or turn', 2),
('xenophobia', 8, 'Intense dislike of people from other countries', 'Xenophobia prevents communities from welcoming newcomers.', 'Greek', 'from Greek "xenos" meaning stranger or foreigner and "phobos" meaning fear', 2),
('omniscient', 8, 'Knowing everything', 'In the story, the narrator is omniscient.', 'Latin', 'from Latin "omnis" meaning all and "sciens" knowing, from "scire" to know', 2),
('idiosyncratic', 8, 'Peculiar to a particular individual', 'Her idiosyncratic style made her work recognizable.', 'Greek', 'from Greek "idiosynkrasia", from "idios" own, "syn" together, and "krasis" mixture or temperament', 3);
